 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    frame_rows = [r for r, row in enumerate(grid) if 5 in row]
    frame_cols = [c for c in range(w) if any(grid[r][c] == 5 for r in range(h))]
    if not frame_rows or not frame_cols:
        return out

    r0, r1 = min(frame_rows) + 1, max(frame_rows) - 1
    c0, c1 = min(frame_cols) + 1, max(frame_cols) - 1
    rm, cm = (r0 + r1 + 1) // 2, (c0 + c1 + 1) // 2

    # Each external marker specifies the color of the corresponding quadrant.
    # The two opposite quadrants repeat those colors diagonally.
    markers = []
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value not in (0, 5):
                markers.append((r, c, value))
    if len(markers) != 2:
        return out

    assignments = {}
    for r, c, value in markers:
        # Markers above/below the frame align with the upper/lower half;
        # markers to the left/right align with the corresponding half.
        upper = r < min(frame_rows) or (r <= max(frame_rows) and r < (min(frame_rows) + max(frame_rows)) / 2)
        left = c < min(frame_cols) or (c <= max(frame_cols) and c < (min(frame_cols) + max(frame_cols)) / 2)
        # In the observed tasks markers lie outside along one axis. Their
        # quadrant is determined by the side of the frame and their position
        # along the other axis relative to its center.
        if r < min(frame_rows):
            upper = True
            left = c < (min(frame_cols) + max(frame_cols)) / 2
        elif r > max(frame_rows):
            upper = False
            left = c < (min(frame_cols) + max(frame_cols)) / 2
        elif c < min(frame_cols):
            left = True
            upper = r < (min(frame_rows) + max(frame_rows)) / 2
        elif c > max(frame_cols):
            left = False
            upper = r < (min(frame_rows) + max(frame_rows)) / 2
        assignments[(upper, left)] = value

    if len(assignments) != 2:
        return out
    for (upper, left), value in list(assignments.items()):
        assignments[(not upper, not left)] = value

    for r in range(r0, r1 + 1):
        for c in range(c0, c1 + 1):
            out[r][c] = assignments[(r < rm, c < cm)]
    return out
